import novamind_api as nm

# 1. Fix D_E09 ad channels - stop linkedin, try search+content+referral
# Keep S1: social_media=150, search_ads=100
# Keep S2: content_marketing=150
# Add S3: content_marketing=20 (small test)
# D_E09: switch to search_ads=60 + content_marketing=60 + referral_program=30 = 150

nm.marketing.set_targeted_ad_spend(targeted_spend={
    'social_media': {
        'S1': 150
    },
    'search_ads': {
        'S1': 100,
        'D_E09': 60
    },
    'content_marketing': {
        'S2': 150,
        'S3': 20,
        'D_E09': 60
    },
    'referral_program': {
        'D_E09': 30
    },
    'linkedin': {}
})
print('Ad spend updated: D_E09 switched from linkedin -> search/content/referral')
print('Added S3 test: content_marketing $20/day')

# 2. Stop E1 targeted dev (was $50/day - wasted on impossible quality target)
# Keep: S2=$600, S3=$300, D_E09=$300
nm.analytics.set_targeted_dev_spend(targeted_spend={
    'S2': 600,
    'S3': 300,
    'D_E09': 300
})
print('Stopped E1 targeted dev (save $50/day). S2=600, S3=300, D_E09=300')

# 3. Verify daily spend unchanged
nm.marketing.set_daily_spend(operations=250, development=1000)
print('Ops=250, Dev=1000 confirmed')

print('All changes applied!')
" 2>&1

